package com.garagedesk.controller; import com.garagedesk.entity.Mechanic; import com.garagedesk.service.MechanicService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/mechanics") public class MechanicController{final MechanicService s;public MechanicController(MechanicService s){this.s=s;}@GetMapping public List<Mechanic> all(){return s.all();}@PostMapping @ResponseStatus(HttpStatus.CREATED)public Mechanic create(@Valid @RequestBody Mechanic x){return s.save(x);}@PutMapping("/{id}")public Mechanic update(@PathVariable Long id,@Valid @RequestBody Mechanic x){return s.update(id,x);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){s.delete(id);}}
